import json

# 定义海阔规则的各个脚本

find_rule_js = """js:
var d = [];
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var page = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
var ch = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && (MY_PARAMS.class || MY_PARAMS.fyclass)) ? (MY_PARAMS.class || MY_PARAMS.fyclass) : 20;

try {
    var rawUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : '';
    var reqUrl = bridgeBase + '/videos?channel=' + ch + '&page=' + page;
    if (rawUrl && rawUrl.indexOf('/videos') !== -1) {
        reqUrl = rawUrl;
    }
    var html = request(reqUrl);
    var res = JSON.parse(html);
    if (!res || !res.ok) {
        throw new Error('Bridge returned error: ' + (res ? res.error : 'empty response'));
    }
    var items = res.items || (res.data && res.data.items) || [];
    for (var i = 0; i < items.length; i++) {
        var it = items[i];
        d.push({
            title: it.name || '未知片名',
            desc: (it.continu ? it.continu + ' · ' : '') + (it.year || ''),
            pic_url: it.pic || '',
            url: bridgeBase + '/detail?id=' + it.id,
            col_type: 'movie_3'
        });
    }
} catch (e) {
    d.push({
        title: '获取列表失败: ' + e.message,
        col_type: 'text_1'
    });
}
setResult(d);
"""

search_find_js = """js:
var d = [];
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var page = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
var kw = (typeof KEYWORD !== 'undefined' && KEYWORD) ? KEYWORD : ((typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) ? MY_KEYWORD : '');

try {
    if (!kw && typeof MY_URL !== 'undefined' && MY_URL) {
        var m = MY_URL.match(/[?&]key=([^&]+)/);
        if (m) {
            kw = decodeURIComponent(m[1]);
        }
    }
    var reqUrl = bridgeBase + '/search?key=' + encodeURIComponent(kw) + '&page=' + page;
    var html = request(reqUrl);
    var res = JSON.parse(html);
    if (!res || !res.ok) {
        throw new Error('Bridge returned error: ' + (res ? res.error : 'empty response'));
    }
    var items = res.items || (res.data && res.data.items) || [];
    for (var i = 0; i < items.length; i++) {
        var it = items[i];
        d.push({
            title: it.name || '未知片名',
            desc: (it.continu ? it.continu + ' · ' : '') + (it.year || ''),
            pic_url: it.pic || '',
            url: bridgeBase + '/detail?id=' + it.id,
            col_type: 'movie_3'
        });
    }
} catch (e) {
    d.push({
        title: '搜索失败: ' + e.message,
        col_type: 'text_1'
    });
}
setResult(d);
"""

detail_find_rule_js = """js:
var d = [];
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : 'http://127.0.0.1:18002';
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');

try {
    var videoId = '';
    var m = currentUrl.match(/[?&]id=([^&]+)/);
    if (m) {
        videoId = m[1];
    }
    if (!videoId) {
        throw new Error('未获取到详情ID: ' + currentUrl);
    }

    var reqUrl = bridgeBase + '/detail?id=' + videoId;
    var html = request(reqUrl);
    var res = JSON.parse(html);
    if (!res || !res.ok) {
        throw new Error('Bridge returned error: ' + (res ? res.error : 'empty response'));
    }
    var detail = res.data || {};
    var cleanTitle = detail.name || '未知片名';

    // 铁律 5: 详情页首个卡片必须显式注入 title: '剧名：' + cleanTitle
    d.push({
        title: '剧名：' + cleanTitle,
        desc: (detail.year ? detail.year + ' · ' : '') + (detail.area ? detail.area + ' · ' : '') + (detail.type || ''),
        pic_url: detail.pic || '',
        url: currentUrl,
        col_type: 'pic_1_card'
    });

    if (detail.content) {
        d.push({
            title: '简介：' + detail.content,
            col_type: 'text_1'
        });
    }

    var parts = detail.parts || [];
    for (var i = 0; i < parts.length; i++) {
        var group = parts[i];
        var playName = group.play_zh || group.play || ('线路 ' + (i + 1));
        d.push({
            title: '【' + playName + '】',
            col_type: 'text_1'
        });

        var eps = group.part || [];
        for (var j = 0; j < eps.length; j++) {
            var epName = eps[j];
            var playParam = {
                id: String(videoId),
                part: String(epName),
                play: String(group.play)
            };
            var lazyPayload = JSON.stringify(playParam);
            var lazyCode = '.js:(() => {\\n' +
                'var bridgeBase = (typeof MY_PARAMS !== "undefined" && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : "http://127.0.0.1:18002";\\n' +
                'var payload = ' + lazyPayload + ';\\n' +
                'var resText = post(bridgeBase + "/play", {\\n' +
                '    body: JSON.stringify(payload),\\n' +
                '    headers: {"Content-Type": "application/json"}\\n' +
                '});\\n' +
                'var res = JSON.parse(resText);\\n' +
                'if (!res || !res.ok || !res.url) {\\n' +
                '    throw new Error("Play resolve failed: " + (res ? res.error : "empty response"));\\n' +
                '}\\n' +
                'var mediaUrl = res.url;\\n' +
                'var headers = res.headers || {};\\n' +
                'var headerParts = [];\\n' +
                'for (var k in headers) {\\n' +
                '    if (headers.hasOwnProperty(k)) {\\n' +
                '        headerParts.push(k + "@" + headers[k]);\\n' +
                '    }\\n' +
                '}\\n' +
                'if (headerParts.length > 0) {\\n' +
                '    return mediaUrl + ";{" + headerParts.join("&&") + "}";\\n' +
                '}\\n' +
                'return mediaUrl;\\n' +
                '})()';

            d.push({
                title: epName,
                url: bridgeBase + '/play?id=' + videoId + '&part=' + encodeURIComponent(epName) + '&play=' + encodeURIComponent(group.play) + '@lazyRule=' + lazyCode,
                col_type: 'text_3'
            });
        }
    }
} catch (e) {
    d.push({
        title: '解析详情失败: ' + e.message,
        col_type: 'text_1'
    });
}
setResult(d);
"""

rule = {
    "title": "动漫共和国概念版",
    "author": "DeepCloud",
    "version": 1,
    "url": "http://127.0.0.1:18002/videos?[REDACTED_QUERY]",
    "class_name": "日漫&国漫&剧场&美漫&特摄&少儿&动态漫&猜你想看",
    "class_url": "20&21&22&23&25&32&26&27",
    "find_rule": find_rule_js,
    "search_url": "http://127.0.0.1:18002/search?[REDACTED_QUERY]",
    "searchFind": search_find_js,
    "detail_col_type": "movie_1",
    "detail_find_rule": detail_find_rule_js
}

with open("rule.json", "w", encoding="utf-8") as f:
    json.dump(rule, f, ensure_ascii=False, indent=2)

print("rule.json generated successfully")
